begin isolation level repeatable read read only;
set local transaction_read_only=on;set local statement_timeout='8s';set local lock_timeout='1s';set local search_path=pg_catalog;
with desired(relation,column_name) as(values ('opportunity_workspace','id'),('opportunity_workspace','company'),('opportunity_workspace','contact'),('opportunity_workspace','email'),('opportunity_workspace','phone'),('opportunity_workspace','industry'),('opportunity_workspace','amount'),('opportunity_workspace','stage'),('opportunity_workspace','seller_id'),('opportunity_workspace','closer_id'),('opportunity_workspace','next_action'),('opportunity_workspace','next_action_at'),('opportunity_workspace','created_at'),('opportunity_workspace','updated_at'),('opportunity_workspace','application_complete'),('opportunity_workspace','application_signed'),('opportunity_workspace','funded_at'),('opportunity_workspace','funded_amount'),('opportunity_workspace','funded_lender_id'),('opportunity_workspace','handed_off_at'),('profiles','id'),('profiles','name'),('profiles','email'),('profiles','role'),('profiles','active'),('mail_accounts','id'),('mail_accounts','email'),('mail_accounts','owner_id'),('lenders','id'),('lenders','name'),('lenders','email'),('tasks','id'),('tasks','opportunity_id'),('tasks','owner_id'),('tasks','title'),('tasks','due_at'),('tasks','status'),('tasks','area'),('offers','id'),('offers','opportunity_id'),('offers','submission_id'),('offers','product'),('offers','amount'),('offers','term'),('offers','cost'),('offers','frequency'),('offers','fees'),('offers','expires_at'),('offers','status'),('offers','created_at'),('submissions','id'),('submissions','opportunity_id'),('submissions','process_id'),('submissions','lender_id'),('submissions','closer_id'),('submissions','status'),('submissions','submitted_at'),('submissions','next_action'),('submissions','next_action_at'),('financing_processes','id'),('financing_processes','opportunity_id'),('financing_processes','sequence_number'),('financing_processes','state'),('financing_processes','classification'),('financing_processes','is_unclassified_archive'),('financing_processes','started_at'),('financing_processes','actual_funded_amount'),('financing_processes','funded_lender_id'),('documents','id'),('documents','opportunity_id'),('documents','kind'),('documents','status'),('documents','storage_path'),('documents','created_at'),('documents','required'),('documents','content_hash'),('case_events','id'),('case_events','opportunity_id'),('case_events','process_id'),('case_events','submission_id'),('case_events','archive_message_id'),('case_events','kind'),('case_events','area'),('case_events','evidence_type'),('case_events','occurred_at'),('mail_conversations_visible','id'),('mail_conversations_visible','opportunity_id'),('mail_conversations_visible','submission_id'),('mail_conversations_visible','process_id'),('mail_conversations_visible','account_id'),('mail_conversations_visible','subject'),('mail_conversations_visible','area'),('mail_conversations_visible','needs_attention'),('mail_conversations_visible','updated_at'),('lead_workspace','id'),('lead_workspace','contact_id'),('lead_workspace','company'),('lead_workspace','contact'),('lead_workspace','email'),('lead_workspace','seller_id'),('lead_workspace','suppressed'),('lead_workspace','opportunity_id'),('lead_workspace','verification'),('lead_workspace','created_at'),('mail_archive_visible','id'),('mail_archive_visible','account_id'),('mail_archive_visible','gmail_thread_id'),('mail_archive_visible','subject'),('mail_archive_visible','sent_at'),('mail_archive_visible','direction'),('mail_archive_visible','nature'),('mail_archive_visible','reply_intent'),('mail_archive_visible','participants'),('messages','id'),('messages','conversation_id'),('messages','direction'),('messages','sender'),('messages','sent_at'),('messages','status'),('messages','area'),('messages','nature'),('messages','reply_intent'),('messages','archive_message_id'),('messages','body'),('pipeline_mail_reviews','id'),('pipeline_mail_reviews','opportunity_id'),('pipeline_mail_reviews','message_id'),('pipeline_mail_reviews','status'),('pipeline_mail_reviews','result')), fields as (
 select d.relation,d.column_name,c.oid,c.relkind,c.relrowsecurity,c.reloptions,a.attnum,
 case when a.attnum is not null then has_column_privilege('authenticated',c.oid,a.attnum,'SELECT') else false end authenticated_select
 from desired d left join pg_namespace n on n.nspname='public' left join pg_class c on c.relnamespace=n.oid and c.relname=d.relation
 left join pg_attribute a on a.attrelid=c.oid and a.attname=d.column_name and a.attnum>0 and not a.attisdropped
),relations as(select relation,max(relkind::text) kind,bool_or(relrowsecurity) rls,bool_or(coalesce('security_invoker=true'=any(reloptions),false)) security_invoker,
 bool_and(oid is not null) relation_present,bool_and(attnum is not null) columns_present,bool_and(authenticated_select) authenticated_select,
 jsonb_agg(jsonb_build_object('column',column_name,'present',attnum is not null,'authenticated_select',authenticated_select) order by column_name) columns
 from fields group by relation)
select jsonb_build_object('observed_at',transaction_timestamp(),'database',current_database(),'database_role',current_user,'read_only',current_setting('transaction_read_only'),
 'relations',(select jsonb_agg(to_jsonb(r) order by r.relation) from relations r),
 'active_role_counts',(select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from(select role::text,count(*)::integer count from public.profiles where active group by role order by role)x),
 'policies',(select coalesce(jsonb_agg(jsonb_build_object('relation',tablename,'policy',policyname,'roles',roles,'command',cmd) order by tablename,policyname),'[]'::jsonb) from pg_policies where schemaname='public' and tablename in(select relation from desired)),
 'authorization_functions',(select coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'definer',p.prosecdef,'search_path',p.proconfig,'definition_hash',md5(p.prosrc)) order by n.nspname,p.proname),'[]'::jsonb) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','s01_i02') and p.proname in('current_app_role','can_case','can_area','can_archive','visible_archive','visible_conversations'))
 ) master_catalog;rollback;
